skin.css:
.wr, .tour-embed{
  --wr-ink:#002A3A;      /* the school's blue */
  --wr-amber:#F9AA3D;    /* the one call to action */
  --wr-on-amber:#4a3211;
  --wr-teal:#2D7389;
  --wr-paper:#F7FAFD;
  --wr-line:#E4EAF0;
  /* Most of a bar's height is air, not mark. At 74 this held a 46px crest with
     14px of padding a side; at 56 it holds a 40px one with 8. The bar loses 18
     pixels of the visitor's picture and the logo loses 6, which is the trade
     worth making — a strip this shallow reads as a rule under the mark rather
     than as a header competing with the photograph. */
  --wr-bar-h:56px;
  --wr-radius:18px;
  --wr-radius-sm:12px;
  /* One family for the whole tour. Change this line and everything follows.
     Source Sans 3 is free, humanist, and the nearest common relative of the
     school's Karmina Sans, which is licensed to them and not to us. Bundled
     with the player, so it needs no network. */
  --wr-font:"Source Sans 3",Poppins,Inter,system-ui,sans-serif;
  /* Floating objects, not panels bolted to an edge. One shadow for all of them:
     that shared weight is most of what makes separate controls read as one
     interface. */
  --wr-lift:0 2px 6px rgb(0 20 30 / .10), 0 10px 30px rgb(0 20 30 / .16);
}
.wr{position:absolute; inset:0; pointer-events:none; font-family:var(--wr-font)}
.wr *{box-sizing:border-box}
.wr a,.wr label,.wr button{pointer-events:auto}

/* --- the bar -------------------------------------------------------------- */
/* A solid white strip across the top, and it is structural rather than
   decorative: the Matterport frame is inset below it, so their chrome and ours
   can never occupy the same pixel. It was removed once for looking heavier than
   a floating crest, and the collision came straight back — their logo and the
   space's name sit exactly where ours did. Paying a bar's height for a frame
   nothing overlaps is the cheaper of the two.

   The mark goes blue inside it. White-on-white is invisible, and the crest has
   always been the school's ink colour on paper. */
.wr-bar{
  position:absolute; top:0; left:0; right:0; height:var(--wr-bar-h);
  display:flex; align-items:center; justify-content:space-between; gap:18px;
  padding:0 24px; background:#fff;
  box-shadow:0 1px 0 var(--wr-line), 0 2px 16px rgb(0 20 30 / .07);
  pointer-events:auto; z-index:30;
}
.wr-brand{display:block; line-height:0}
.wr-bar .wr-logo{height:40px; color:var(--wr-ink)}
.wr-logo{height:62px; width:auto; display:block; color:#fff}

/* --- the two utilities ---------------------------------------------------- */
/* Middle of the left edge, stacked. Away from the bar because they are not
   navigation — one goes back to where the tour began, the other opens the
   school's own details — and away from the bottom because that is where
   Matterport puts its own controls.

   The house is back and now has a job. It was deleted when the crest was the
   way home and a second control for the same thing was one too many; with the
   crest inside a bar and no longer a link, the way home has to be somewhere. */
/* One pill holding both, not two amber discs. Amber is the tour's single call
   to action — it is on "Apply Now" and on the building you are currently inside
   — and spending it on two permanent utilities is what made it stop meaning
   anything. Paper-white and see-through instead: the photograph stays visible
   behind them, which is the same reason the labels have no card. */
.wr-side{
  /* Centred on the picture, not on the window. A bar takes height out of what
     the visitor is actually looking at, so 50% of the viewport sits low by half
     the bar — enough to read as "nearly centred", which is worse than either
     alternative. Half the bar's height puts it back on the middle of the
     photograph. */
  position:absolute; left:20px; top:calc(50% + var(--wr-bar-h) / 2); transform:translateY(-50%);
  /* align-items:center is load-bearing: a column flexbox stretches its
     children across its width by default, so anything that ever set a width
     here in one place and not the other would quietly turn one of the two
     circles into an oval. Equal padding and gap, so the pill is the buttons
     plus one even margin all the way round. */
  display:flex; flex-direction:column; align-items:center; gap:5px; padding:5px;
  z-index:30;
  background:rgb(255 255 255 / .72); border-radius:999px;
  box-shadow:var(--wr-lift); backdrop-filter:blur(8px) saturate(1.2);
}
.wr-home,
.wr-info{
  width:44px; height:44px; flex:none; display:grid; place-items:center;
  aspect-ratio:1; border-radius:50%; cursor:pointer; text-decoration:none;
  transition:background .16s, color .16s, transform .16s;
}
/* Each with its own disc. White for the way back, amber for the one that opens
   something — the same amber that marks the tour you are standing in and the
   Apply button, so the colour keeps meaning "this one does something" rather
   than being spent on decoration. */
.wr-home{background:#fff; color:var(--wr-ink)}
.wr-info{background:var(--wr-amber); color:var(--wr-on-amber)}
.wr-home:hover{background:var(--wr-paper); transform:scale(1.06)}
.wr-info:hover{background:#ffbd63; transform:scale(1.06)}
.wr-home:focus-visible,
.wr-info:focus-visible{outline:2px solid var(--wr-amber); outline-offset:2px}
/* Open is a state worth seeing: the info button stays lit while its panel is. */
.wr-flag:checked ~ .wr-side .wr-info{background:var(--wr-ink); color:#fff}
.wr-home .wr-i,
.wr-info .wr-i{width:21px; height:21px}

/* Nothing but the door, until the door is opened.
   The chrome used to sit on top of the splash, which put the crest on screen
   twice — once in the corner and once in the middle of the card — and lit the
   building nav at full strength over a dimmed photograph, so the first thing a
   visitor saw was three competing invitations. Every tour builder that has been
   at this a while shows the splash alone; this now does too. Faded rather than
   switched, so the interface assembles itself behind the card going away. */
.wr-bar,
.wr-badge{
  opacity:0; visibility:hidden;
  transition:opacity .5s ease-out .12s, visibility .5s;
}
.wr-started:checked ~ .wr-bar,
.wr-started:checked ~ .wr-side{opacity:1; visibility:visible}
/* Its own rule, because the badge rests below full opacity and the shared one
   above would hold it at 1 and take the hover with it. */
.wr-started:checked ~ .wr-badge{opacity:.86; visibility:visible}


/* The SkyView tab. Flush to the bottom edge, because the artwork is a tab —
   rounded along the top, square along the bottom — and floating it above the
   edge turns it into a sticker of a tab. Under the splash rather than over it,
   and it fades up with the rest of the interface rather than being the one
   thing already there.
   Small: 96px is about a quarter of the artwork's own width, which is what a
   credit should take on somebody else's photograph. */
.wr-badge{
  position:absolute; bottom:0; right:22px; z-index:40;
  display:block; width:96px; line-height:0; user-select:none;
  opacity:.86; transition:opacity .16s;
}
.wr-badge img{width:100%; height:auto; display:block}
/* Opacity alone on hover. It is a credit on somebody else's photograph, so it
   should acknowledge the cursor without behaving like one of the controls. */
.wr-badge:hover{opacity:1}
.wr-badge:focus-visible{outline:2px solid var(--wr-amber); outline-offset:3px; opacity:1}
/* No data-tour-embed on it, deliberately: that verb opens a url *inside* the
   tour, which is right for the three Matterports and wrong for leaving the tour
   altogether. This one is a way out, so it goes to a new tab like the info
   panel's links do. */
/* Gone on a phone, where the pill itself has moved to the bottom and the two
   would be sharing a strip about a thumb wide. Gone behind a Matterport too:
   theirs runs its own chrome along the bottom of the frame, which is exactly
   why our controls step aside to the one free corner while one is open. */
/* Matched through the same .wr-started the reveal uses, or it loses: the
   reveal is (0,2,1) and a bare attribute selector is (0,2,0), so the badge came
   back at .86 the moment a Matterport opened — straight over their own controls
   in that corner. */
[data-tour-embedded] .wr-started:checked ~ .wr-badge,
[data-tour-embedded] .wr-badge{opacity:0; visibility:hidden}
/* The three tours are one object. Three separate links floating on a
   photograph read as debris; segmented, they read as a choice. */
/* Inside the bar the pill container has nothing to do: it existed to lift three
   links off a photograph, and there is no photograph behind them now. White on
   white with a shadow would just be a seam. */
.wr-tours{
  display:flex; align-items:center; gap:2px;
  background:none; box-shadow:none; padding:0; backdrop-filter:none;
}
.wr-tours a{
  display:flex; align-items:center; justify-content:center; gap:.3em;
  height:38px; padding:0 17px; line-height:1;
  border-radius:999px; text-decoration:none;
  color:var(--wr-ink); font-size:15px; font-weight:500; white-space:nowrap;
  transition:background .16s, color .16s;
}
/* The hover carries the school's own amber rather than a grey wash, so the
   segment you are about to choose already looks like the segment you are in —
   the filled state below is the same colour at full strength. Not applied to
   the open tour: it is already amber, and a hover that lightens the current
   item reads as leaving it.

   Colour alone, no shadow. This briefly had a lift and a drop-shadow under it,
   which contradicted the rule stated a few hundred lines down in this same
   file: a shadow that appears under a control when you point at it is the
   thing that reads as cheap. The pills sit inside one white bar that already
   has the only shadow this control needs. */
.wr-tours a:not([data-tour-embed-current]):hover{
  background:color-mix(in srgb, var(--wr-amber) 20%, var(--wr-paper));
}
.wr-tours a:focus-visible{outline:2px solid var(--wr-amber); outline-offset:2px}
.wr-short{display:none}
/* Which tour you are standing in. Filled, not underlined — on a segmented
   control the filled segment is the one you are in, and that reads at a glance
   in a way a 2px rule does not. */
.wr-tours a[data-tour-embed-current]{
  background:var(--wr-amber); color:var(--wr-on-amber); font-weight:600;
}

/* The old free-floating info button lived here — 48px, amber, its own shadow —
   and survived the move into the pill because it sat *after* the new rule in
   this file. Same specificity, so it won: the house came out 44 and the info 48,
   which is also why the pill's side padding read as 7 on one and 5 on the other.
   A flex column sizes itself to its widest child and centres the rest. */
.wr-i{width:22px; height:22px; display:block}

/* --- the panel ----------------------------------------------------------- */
/* A card that floats under the button that opened it, not a drawer welded to
   the window edge. It leaves the photograph visible around three of its sides,
   which is the point of putting an interface on a picture at all. */
/* A drawer down the left, from the bar to the floor, and square.
   It used to be a rounded card floating at the top right — which is where the
   controls were then, and they are not any more: the button that opens it now
   lives on the left edge, and a panel that appears at the opposite corner from
   the thing you pressed is a panel you have to go looking for.
   Square because it meets two edges. Rounding a corner that is flush against
   the side of the window draws a line where there is no edge, and the bar above
   it is square too. */
.wr-panel{
  position:absolute; top:var(--wr-bar-h); left:0; bottom:0; width:352px;
  max-width:100%;
  display:flex; flex-direction:column; gap:12px;
  padding:16px; overflow:auto; pointer-events:auto;
  background:var(--wr-paper); border-radius:0;
  box-shadow:0 0 40px rgb(0 20 30 / .22);
  /* Above the pair. On a phone the panel is a sheet and nothing slides out of
     its way, so without this the two buttons float on top of the sheet that is
     covering them. */
  z-index:40;
  opacity:0; transform:translateX(-100%); visibility:hidden;
  transition:opacity .28s ease-out, transform .28s cubic-bezier(.22,1,.36,1), visibility .28s;
}
.wr-flag:checked ~ .wr-panel{opacity:1; transform:none; visibility:visible}
/* The pair rides out on top of it rather than being covered by it. */
.wr-flag:checked ~ .wr-side{transform:translate(352px, -50%)}
/* Its own rule rather than a share of the group above plus an override of the
   group's transition — the shorthand replaced it wholesale anyway, so the two
   were one rule pretending to be two. */
.wr-side{
  opacity:0; visibility:hidden;
  transition:transform .28s cubic-bezier(.22,1,.36,1), opacity .5s ease-out .12s, visibility .5s;
}
@media (prefers-reduced-motion:reduce){ .wr-panel{transition:none} }

.wr-panel-head{
  display:flex; align-items:center; justify-content:space-between; gap:10px;
  padding:2px 4px 0; color:var(--wr-ink); font-weight:600; font-size:15px;
  flex:none;
}
/* The cards float to the middle of whatever room is left, and the title stays
   at the top where a title belongs. Auto margins rather than justify-content:
   center, because this panel scrolls — centring a flex container clips the top
   of the content when it overflows, whereas an auto margin resolves to zero the
   moment there is no free space to absorb. Same look when it fits, no lost
   first card when it does not. */
.wr-panel-head + .wr-card{margin-top:auto}
.wr-panel > .wr-card:last-child{margin-bottom:auto}
.wr-close{color:var(--wr-ink); opacity:.5; cursor:pointer; line-height:0; flex:none}
.wr-close:hover{opacity:1}
.wr-close .wr-i{width:18px; height:18px}

.wr-card{flex:none; background:#fff; border-radius:var(--wr-radius-sm); box-shadow:0 1px 3px rgb(0 20 30 / .07); overflow:hidden}
.wr-card > a{
  display:block; padding:12px 16px; text-align:center; text-decoration:none;
  color:var(--wr-ink); font-size:15px;
}
.wr-card:not(.wr-socials):not(.wr-contact) > a + a:not(.wr-apply){box-shadow:inset 0 1px 0 var(--wr-line)}
.wr-card:not(.wr-socials):not(.wr-contact) > a:not(.wr-apply):hover{background:var(--wr-paper)}
/* Flush to the card, not floating inside it. The 8px margin here let the card's
   own white show all the way round the amber, which reads as an outline nobody
   drew — and a rounded rectangle inside a rounded rectangle is two borders
   where the design has one. The card already clips, so the bottom corners come
   for free. */
.wr-apply{
  background:var(--wr-amber); color:var(--wr-on-amber) !important;
  font-weight:600; letter-spacing:.01em; padding:15px !important;
  margin:0; border-radius:0;
}
.wr-apply:hover{background:#ffbd63 !important}

/* One fact per row, each with its own icon, all on one left margin — the column
   of icons does the aligning a wall of text cannot. Three of the four are live;
   the fax is not, because nothing useful happens when you press a fax number. */
.wr-contact{padding:4px 0}
.wr-card .wr-row{
  display:flex; align-items:flex-start; gap:12px;
  padding:10px 16px; color:var(--wr-ink); text-decoration:none; font-size:14px;
  line-height:1.5; transition:color .14s;
}
.wr-card .wr-row .wr-i{width:18px; height:18px; flex:none; margin-top:1px; color:var(--wr-teal)}
.wr-card .wr-row b{display:block; font-weight:600}
.wr-card .wr-row span{text-align:left}
.wr-card .wr-row.is-static{color:rgb(0 42 58 / .55)}
.wr-card .wr-row.is-static .wr-i{color:rgb(0 42 58 / .28)}
.wr-card a.wr-row:hover{color:var(--wr-teal)}
.wr-card a.wr-row:hover .wr-i{color:var(--wr-amber)}

/* The mark recolours; nothing is drawn behind it. */
/* Three marks on a row, and nothing else in the card — so the padding is the
   whole of its height and 14px a side made a band deeper than the row it holds.
   Colour on hover and nothing else: a lift is for something you are about to
   press *into* the page, and these leave it. */
.wr-socials{display:flex; gap:14px; padding:9px 16px; justify-content:center}
.wr-socials a{line-height:0; color:var(--wr-ink); transition:color .16s}
.wr-socials a:hover{color:var(--wr-teal); background:none !important}
.wr-social{width:30px; height:30px; display:block}

/* --- the embedded tour ---------------------------------------------------- */
/* Inset below the bar, which is the entire reason the bar exists. Matterport
   draws its own logo and the space's name across the top-left of its frame; run
   full-bleed, that lands underneath ours and neither is readable. Given a strip
   of its own, nothing of theirs and nothing of ours can ever occupy the same
   pixel, and no control has to step aside for the duration. */
.tour-embed{top:var(--wr-bar-h); height:calc(100% - var(--wr-bar-h))}
.wr-back{
  /* Under the bar, against the right edge — over the Matterport rather than
     beside our own nav, because it belongs to the thing it closes. Their own
     chrome runs along the bottom and up the left, so the top right of the frame
     is the corner they leave empty. */
  position:absolute; top:calc(var(--wr-bar-h) + 14px); right:24px; z-index:30;
  display:none; align-items:center; justify-content:center; gap:8px; flex:none;
  height:48px; padding:0 20px 0 16px; line-height:1;
  background:#fff; color:var(--wr-ink); border:0; border-radius:999px;
  font:inherit; font-family:var(--wr-font);
  font-size:15px; font-weight:500; cursor:pointer; box-shadow:var(--wr-lift);
  pointer-events:auto;
}
[data-tour-embedded] .wr-back{display:flex}
.wr-back:hover{background:var(--wr-paper)}
.wr-back .wr-i{width:18px; height:18px}
/* --- while a Matterport is open ------------------------------------------ */
/* Matterport's own chrome sits top-left (its logo and the space's name),
   bottom-left (playback, floorplan, walk) and bottom-right (share, menu). The
   top-right corner is the one it leaves empty, which is why our cluster lives
   there and why Urban Academy put its "Back" button in the same place.

   That leaves exactly one collision: our crest, which lands on theirs. So it
   steps aside for the duration rather than the whole interface growing a bar to
   avoid it. The alternative is to inset the frame from the top — but an inset
   that exists only to dodge a logo is the bar again, and it costs the visitor
   the height of it in the thing they actually asked to see. */
/* The crest no longer hides — inset below the bar, it never meets theirs.
   The pair on the left does go behind the frame, which is a reversal worth
   writing down: it used to be kept visible on purpose, because when the info
   button lived in the top-right cluster it vanished for the whole visit and
   there was no way back to the school's details. That reasoning died with the
   bar. Matterport runs its own controls up the left edge of its frame, so two
   buttons floating over them is our interface talking over theirs — and Close
   is right there, one tap from everything.
   Under the frame at 10 rather than hidden: the embed is opaque and sits at 20,
   so this is the same thing to look at and one number to put back. */
[data-tour-embedded] .wr-side{z-index:10}

/* The info panel stays reachable throughout: it is about the school — address,
   admissions, how to apply — not about the panorama, and a visitor standing in
   the library is exactly who wants it. Close sits in the same row rather than
   floating separately, so nothing overlaps the panel. */

/* --- hotspot labels ------------------------------------------------------- */
/* Circle hotspots are PSV markers, outside .wr, so the family is named rather
   than inherited. */
.vtc-circle-name{
  font-family:"Source Sans 3",Poppins,Inter,system-ui,sans-serif;
  font-weight:600; letter-spacing:.01em;
}
/* Name above the disc: at the bottom of the frame it is the first thing to fall
   off the edge, and the pointer sits under it. */
.vtc-hotspot--circle{flex-direction:column-reverse}

/* --- areas ---------------------------------------------------------------- */
/* Invisible until pointed at, then the shape appears exactly. An outline drawn
   permanently over a building is a diagram; the photograph is the thing worth
   looking at, and the callouts already say what everything is. !important
   because Photo Sphere Viewer writes fill and stroke as inline style on the
   path, and inline is the only thing this has to beat. */
path.vtc-hotspot-marker{
  fill-opacity:0 !important;
  stroke-opacity:0 !important;
  transition:fill-opacity .18s ease-out, stroke-opacity .18s ease-out;
  cursor:pointer;
}
/* data-tour-hover as well as :hover, and that is not decoration. The engine
   puts it on every hotspot sharing a hoverGroup, so pointing at the Junior
   School *label* lights the Junior School *outline* and the other way round.
   Without it here the area would take the fill from the runtime's own rule and
   still have no visible edge, because stroke-opacity is held at 0 above and
   only :hover was lifting it — a filled shape with no outline, on the one
   interaction the pairing exists for. */
path.vtc-hotspot-marker:hover,
path.vtc-hotspot-marker:focus-visible,
path.vtc-hotspot-marker[data-tour-hover]{
  /* An outline, not a filled shape. A quarter-opaque white panel over a
     building hides the building, which is the thing being pointed at; the edge
     is what says "this, exactly this", and the fill only has to separate inside
     from outside. */
  fill-opacity:.12 !important;
  stroke-opacity:1 !important;
  stroke-width:2.5px !important;
}

/* Nothing but the door, and that has to include the panoramas' own markers.
   They are Photo Sphere Viewer's, drawn outside .wr entirely, so the fade that
   takes the bar and the badge away cannot reach them — labels and a navigation
   circle showed straight through the splash, and on a phone two of them were
   sliced off mid-word at the edge of the screen. Reached here through :has on
   the gate itself, since there is no ancestor the two share. */
body:has(.wr-started:not(:checked)) .psv-marker{
  opacity:0 !important;
  transition:opacity .45s ease-out;
}

/* --- the door ------------------------------------------------------------- */
/* A tour needs somewhere to begin. It also buys the first panorama a moment to
   arrive, so nobody's first impression is a blurry base image sharpening.
   A checkbox and a sibling selector, like the info panel — the skin carries no
   script, so the gate has to be CSS, and that is also why it works identically
   in the editor, in Preview and in the export. */
.wr-splash{
  position:absolute; inset:0; z-index:60; display:grid; place-items:center;
  padding:24px; pointer-events:auto;
  /* A gradient rather than a flat wash, and half the blur it had. The old one
     was 55% black over blur(3px), which hid the thing the visitor came to see
     and made the door look like a loading screen. Weighted to the bottom, where
     the type sits, so the campus is legible across the top and the words still
     have something to sit on. */
  background:linear-gradient(180deg, rgb(0 18 28 / .34) 0%, rgb(0 18 28 / .52) 46%, rgb(0 18 28 / .72) 100%);
  backdrop-filter:blur(1.5px);
  transition:opacity .45s ease-out, visibility .45s;
}
.wr-started:checked ~ .wr-splash{opacity:0; visibility:hidden; pointer-events:none}
.wr-splash-card{
  display:flex; flex-direction:column; align-items:center; gap:20px;
  text-align:center; max-width:440px;
}
.wr-splash-card .wr-logo{height:96px; color:#fff; filter:drop-shadow(0 3px 16px rgb(0 15 25 / .6))}
.wr-splash-card p{
  margin:0; color:#fff; font-size:17px; line-height:1.5; opacity:.92;
  text-shadow:0 1px 6px rgb(0 15 25 / .7);
}
/* What is actually in here, in numbers. The line above says what it feels
   like; a visitor deciding whether to spend three minutes wants to know the
   size of the thing. Small and quiet, so it informs without competing. */
.wr-splash-meta{
  font-size:13px !important; letter-spacing:.04em; text-transform:uppercase;
  opacity:.62 !important; font-weight:600;
}

/* The card arrives in order rather than all at once — the whole difference
   between a screen appearing and a screen being presented. The button is faded
   rather than raised, deliberately: forwards keeps an animation's transform
   winning over a normal declaration, so raising it here would kill its own
   hover lift. */
.wr-splash-card > *{opacity:0; animation:wr-rise .7s cubic-bezier(.22,1,.36,1) forwards}
.wr-splash-card > .wr-start{animation-name:wr-appear}
.wr-splash-card > *:nth-child(1){animation-delay:.10s}
.wr-splash-card > *:nth-child(2){animation-delay:.24s}
.wr-splash-card > *:nth-child(3){animation-delay:.34s}
.wr-splash-card > *:nth-child(4){animation-delay:.46s}
@keyframes wr-rise{from{opacity:0; transform:translateY(14px)} to{opacity:1; transform:none}}
@keyframes wr-appear{from{opacity:0} to{opacity:1}}
.wr-start{
  cursor:pointer; background:var(--wr-amber); color:var(--wr-on-amber);
  font-weight:600; font-size:16px; letter-spacing:.01em;
  padding:14px 30px; border-radius:var(--wr-radius-sm); box-shadow:var(--wr-lift);
  transition:background .16s, transform .16s;
}
.wr-start:hover{background:#ffbd63; transform:translateY(-1px)}

/* Three sentences, one at a time, then gone.
   They used to appear together and say what the visitor could already see —
   "drag to look around" beside two more pills is a row of labels, not teaching.
   Worse, the stagger never ran: the animation was on the container and the
   animation-delays were on the spans, which had no animation of their own, so
   all three arrived on the same frame. Fixed by animating the spans and
   stacking them in one grid cell, so each replaces the last in the same place
   and the eye has one thing to read at a time.
   Nothing to dismiss, because a dismiss button is a fourth thing to explain. */
.wr-hints{
  position:absolute; left:50%; bottom:104px; z-index:50;
  display:grid; place-items:center; transform:translateX(-50%);
  visibility:hidden; pointer-events:none; white-space:nowrap;
}
.wr-hints span{
  grid-area:1/1;            /* all in the same cell, so they take turns */
  display:flex; align-items:center; gap:9px;
  background:rgb(0 20 30 / .62); color:#fff; font-size:13px; font-weight:500;
  padding:8px 15px 8px 12px; border-radius:999px;
  backdrop-filter:blur(4px);
  opacity:0;
}
/* Each icon does the thing its sentence describes, which is the difference
   between a caption and a demonstration: the hand slides, the circle throbs
   the way the hotspots on the photograph do, and the door leans open. Amber,
   so the eye lands on the picture of the gesture before the words. Short loops
   because a pill is only on screen for about three seconds. */
.wr-hints .wr-i{width:17px; height:17px; flex:none; color:var(--wr-amber)}
.wr-hints span:nth-child(1) .wr-i{animation:wr-swipe 1.7s ease-in-out infinite}
.wr-hints span:nth-child(2) .wr-i{animation:wr-throb 1.9s ease-in-out infinite}
.wr-hints span:nth-child(3) .wr-i{animation:wr-step 2s ease-in-out infinite}
@keyframes wr-swipe{0%,100%{transform:translateX(-3px) rotate(-6deg)} 50%{transform:translateX(3px) rotate(6deg)}}
@keyframes wr-throb{0%,100%{transform:scale(1); opacity:.8} 50%{transform:scale(1.16); opacity:1}}
@keyframes wr-step{0%,100%{transform:translateX(0)} 55%{transform:translateX(3px)}}
.wr-started:checked ~ .wr-hints{visibility:visible}
.wr-started:checked ~ .wr-hints span{animation:wr-hint 3.1s ease-out forwards}
/* The last one holds longest: it is the only one a visitor cannot guess. */
.wr-started:checked ~ .wr-hints span:nth-child(1){animation-delay:.8s}
.wr-started:checked ~ .wr-hints span:nth-child(2){animation-delay:3.7s}
.wr-started:checked ~ .wr-hints span:nth-child(3){animation-delay:6.6s; animation-duration:4s}
@keyframes wr-hint{
  0%{opacity:0; transform:translateY(9px)}
  10%{opacity:1; transform:none}
  82%{opacity:1; transform:none}
  100%{opacity:0; transform:translateY(-7px)}
}
@media (prefers-reduced-motion:reduce){
  .wr-started:checked ~ .wr-hints span{animation:none; opacity:0}
  .wr-hints .wr-i{animation:none}
  .wr-splash-card > *{animation:none; opacity:1}
}

/* --- labels --------------------------------------------------------------- */
/* White, and no card. The photograph supplies the colour; a shadow on the type
   is what carries it over a bright roof and a dark hedge alike. A box behind
   every caption is what made the old ones look like buttons. */
.vtc-callout{font-family:"Source Sans 3",Poppins,Inter,system-ui,sans-serif}
.vtc-callout__card{
  background:none !important; box-shadow:none !important;
  border-radius:0 !important;
  /* No card — but keep one edge. The upright IS this border, which is why it is
     exactly as tall as the lines inside and grows when one is added. */
  border:0 !important;
  border-left:2px solid rgb(255 255 255 / .92) !important;
  padding:2px 0 2px 14px !important;
  display:flex; flex-direction:column; align-items:flex-start; gap:8px;
}
.vtc-callout__name{
  font-size:17px; font-weight:600; letter-spacing:.01em; color:#fff;
  /* One line. A place name broken across two is a label that has stopped
     pointing at one thing. */
  white-space:nowrap;
  text-shadow:0 1px 3px rgb(0 15 25 / .75), 0 0 18px rgb(0 15 25 / .45);
}
/* The second line exists only on a callout that goes somewhere, so this rule
   is the whole visible difference between a caption and a way in. A quiet
   white pill rather than a filled amber one — it should read as pressable,
   not shout. */
.vtc-callout__note{
  font-size:12.5px; font-weight:600; letter-spacing:.02em;
  color:var(--wr-ink, #002A3A);
  background:rgb(255 255 255 / .94);
  /* A bit round. A pill reads as a chip and a square as a panel; this is a
     button. */
  padding:6px 12px; border-radius:7px; white-space:nowrap;
  box-shadow:0 2px 8px rgb(0 15 25 / .3);
  transition:background .16s, transform .16s;
}
.vtc-hotspot-marker:hover .vtc-callout__note,
[data-tour-hover] .vtc-callout__note{
  background:var(--wr-amber, #F9AA3D); transform:translateY(-1px);
}
/* Only the ones that go somewhere react to the pointer. */
.vtc-hotspot-marker:has(.vtc-callout__note){cursor:pointer}

/* The labels are simply there.
   They used to draw themselves in as the camera came round to each one, keyed
   off data-tour-near — the leader growing and the card unfolding behind it. It
   demonstrated well and lived badly: on a pan across the campus every label in
   the frame was mid-animation, and turning back and forth made the same five
   captions appear and vanish and appear again. An entrance is a thing that
   happens once; this one happened every time the visitor looked away, which is
   what made it read as flicker rather than as motion.
   The anchor dot still ripples once on approach — a dot marking a place is not
   the same as the caption dealing itself onto the photograph. */
.vtc-callout__leader{opacity:.9}
/* Mirrored: the upright on the right, the words to its left. */
.vtc-callout--right .vtc-callout__card{
  padding:2px 14px 2px 0 !important;
  border-left:0 !important;
  border-right:2px solid rgb(255 255 255 / .92) !important;
}

/* --- micro-interactions --------------------------------------------------- */
/* Small, fast, and only on things that respond to a pointer. The rule
   throughout: 120-180ms, ease-out, and transform or opacity only, so none of
   this is paint work while somebody is dragging the picture.

   One ease for everything, because a set of controls that each spring
   differently reads as several interfaces stapled together. */
.wr-tours a,.wr-info,.wr-back,.wr-start,.wr-apply,.wr-card > a,
.wr-brand,.wr-socials a,.wr-close{
  transition-timing-function:cubic-bezier(.22,1,.36,1);
}
/* No press-scale. It shrank the whole button including its background, so a
   filled control appeared to pull away from its own edges for the length of a
   click — most visible on the panel's rows and on Apply Now, where the amber
   left a rim of card behind it. The hover state already says the control is
   live; a click needs no second confirmation that lasts 90 milliseconds. */

/* The panel's cards arrive together but not at once. 40ms apart is under the
   threshold where it reads as a sequence and over the one where it reads as a
   single jump. */
.wr-flag:checked ~ .wr-panel .wr-card{
  animation:wr-rise .34s cubic-bezier(.22,1,.36,1) backwards;
}
.wr-flag:checked ~ .wr-panel .wr-card:nth-child(2){animation-delay:.04s}
.wr-flag:checked ~ .wr-panel .wr-card:nth-child(3){animation-delay:.08s}
.wr-flag:checked ~ .wr-panel .wr-card:nth-child(4){animation-delay:.12s}
@keyframes wr-rise{from{opacity:0; transform:translateY(8px)}to{opacity:1; transform:none}}

/* The row you are about to press leans in. */
.wr-card:not(.wr-socials):not(.wr-contact) > a{transition:background .16s, padding-left .16s}
.wr-card:not(.wr-socials):not(.wr-contact) > a:hover{padding-left:22px}

/* Keyboard users get the same amber the pointer does, everywhere, once. */
.wr a:focus-visible,.wr label:focus-visible,.wr button:focus-visible{
  outline:2px solid var(--wr-amber); outline-offset:3px; border-radius:4px;
}

/* The mark acknowledges a press without moving the page. */
.wr-brand:active{transform:scale(.985)}

@media (prefers-reduced-motion:reduce){
  .wr-flag:checked ~ .wr-panel .wr-card{animation:none}
  .wr-tours a:active,.wr-info:active,.wr-back:active,.wr-start:active,
  .wr-apply:active,.wr-card > a:active,.wr-brand:active{transform:none}
  .wr-card:not(.wr-socials):not(.wr-contact) > a:hover{padding-left:16px}
}

/* --- narrower ------------------------------------------------------------- */
@media (max-width:900px){
  .wr-bar{padding:0 16px}
  .wr-bar .wr-logo{height:36px}
  .wr-tours a{height:34px; padding:0 13px; font-size:14px}
  .wr-panel{top:calc(var(--wr-bar-h) + 12px); right:18px; width:320px}
}

/* Phone. The bar loses its plate and keeps only the mark — a white strip is a
   third of a small screen's width of nothing, and on a phone the Matterport
   opens to a frame that needs every pixel. The three buildings go to the
   bottom, where a thumb is, which is also the one edge our own controls are
   not using. */
@media (max-width:640px){
  .wr-bar{
    background:none; box-shadow:none; height:auto; padding:14px;
    justify-content:flex-start;
  }
  /* White again, because it is back over the photograph. */
  .wr-bar .wr-logo{height:38px; color:#fff; filter:drop-shadow(0 2px 10px rgb(0 20 30 / .55))}

  /* A real bar, edge to edge, and the same bargain as the one at the top of a
     desktop: it costs its own height and in exchange the Matterport ends above
     it and nothing of theirs is ever underneath anything of ours. A floating
     pill could not do that — a frame cannot stop short of something that is
     hovering over it. */
  .wr-tours{
    position:fixed; left:0; right:0; bottom:0; transform:none;
    height:var(--wr-bar-h); padding:0 8px; gap:4px; max-width:none;
    justify-content:center; border-radius:0;
    background:#fff; backdrop-filter:none;
    box-shadow:0 -1px 0 var(--wr-line), 0 -2px 16px rgb(0 20 30 / .08);
  }
  /* The full names wherever they fit. Measured at the phone's own font and
     padding, the three come to 355px: comfortable on a 375 screen and up,
     which is most phones in use. Only below that do they shorten. */
  .wr-tours a{height:34px; padding:0 13px; font-size:14px}

  /* The pair stays where it is on a desktop — middle of the left edge — and
     only shrinks. Moved up above the bottom bar it landed in the same strip as
     the hints, which is three things stacked in the corner a thumb rests in.
     Vertically centred it clears the bar below it and the hints above it, and
     it is in the same place on both, which is one less thing to relearn. */
  /* The bar is at the foot here, so the picture's middle is above the
     window's. */
  .wr-side{left:12px; gap:8px; top:calc(50% - var(--wr-bar-h) / 2)}
  .wr-home,.wr-info{width:44px; height:44px}

  /* The sentences wrap rather than run off the edge, and sit clear of the
     buttons on both sides. */
  /* Nearly edge to edge. 96px of margin was pinching a sentence that fits on
     one line into two with room to spare either side; 24 leaves a thumb's
     clearance and lets all three sit on a single line down to a 320px screen.
     Still allowed to wrap, because a longer sentence in another language must
     break rather than run off the edge. */
  .wr-hints{bottom:calc(var(--wr-bar-h) + 18px); max-width:calc(100% - 24px)}
  .wr-hints span{white-space:normal; text-wrap:balance; line-height:1.3; font-size:13px}

  /* Above the bottom bar instead of below a top one. Full height at the top
     because the mark up there has no plate behind it — which leaves exactly one
     collision, our crest against theirs, both of which sit top-left. So on a
     phone the crest steps aside for the duration; there is no room to give it a
     strip of its own without taking it from the thing the visitor asked to see. */
  .tour-embed{top:0; height:calc(100% - var(--wr-bar-h))}
  [data-tour-embedded] .wr-bar{opacity:0; pointer-events:none; transition:opacity .2s}
  /* With the word gone this is an icon button, so it has to be a circle rather
     than a pill that happens to be nearly square. It was 46 by 44 — the side
     padding left over from the label, plus a gap holding a space between the
     icon and nothing — which at a 999px radius is a very slightly flattened
     circle. Fixed width, no padding, no gap. */
  .wr-back{top:14px; right:14px; width:44px; height:44px; padding:0; gap:0}
  .wr-back span{display:none}

  /* As tall as its contents, and it may take nearly the whole screen — there
     are eight links, an address, three phone numbers and a row of socials in
     here, and capping it at 82vh left the last card half off the bottom on
     every phone. Taller than the content it never gets, and past the cap it
     scrolls. */
  .wr-panel{
    top:auto; bottom:0; left:0; right:0; width:100%;
    height:auto; max-height:calc(100% - 14px);
    border-radius:var(--wr-radius) var(--wr-radius) 0 0;
    transform:translateY(100%) scale(1); transform-origin:bottom center;
    padding:14px 14px 22px;
  }
  .wr-flag:checked ~ .wr-panel{transform:translateY(0)}
  /* The sheet comes up from the floor here, so nothing slides out of its way. */
  .wr-flag:checked ~ .wr-side{transform:translateY(-50%)}
  .wr-badge{display:none}
}

/* Under 370 the full names stop fitting — 355px of labels in a 360px window is
   five pixels of slack, which is not slack. "Junior" and "Senior" are the words
   carrying the difference, so "School" is the one that shortens. */
@media (max-width:369px){
  .wr-long{display:none}
  .wr-short{display:inline}
}
/* And under 360 even the short form needs the padding back. */
@media (max-width:359px){
  .wr-tours a{padding:0 10px; font-size:13px}
}

/* Sideways on a phone there is almost no height to spare. */
@media (max-height:520px) and (orientation:landscape){
  .wr-logo{height:34px}
  .wr-panel{top:0; bottom:0; left:0; right:auto; width:320px; max-height:100%; border-radius:0; transform:translateX(-100%)}
  .wr-flag:checked ~ .wr-panel{transform:none}
}
